// Beginner sequence for the seven stable Section 4 routes. The same stored
// calculation is revisited from memory, processor, transfer and source-code views.
import { section4Programs, programListing } from './course-v3-section4-programs.mjs';

const ids = (requirement, ...numbers) => numbers.map(number => `S4.${String(requirement).padStart(2, '0')}.A${String(number).padStart(2, '0')}`);
const diagram = name => `/assets/course-v3/section-4/${name}.svg`;
const table = (headers, rows) => ({ headers, rows });
const step = (title, body, extra = {}) => ({ title, body, ...extra });
const worked = (title, setup, steps, conclusion) => ({ title, setup, steps, conclusion });
const listing = name => programListing(section4Programs[name]);
const sourceMemory = table(['Address', 'Contents', 'Use in this program'], [[0, 'LDD 4', 'Load the value at address 4'], [1, 'ADD 5', 'Add the value at address 5'], [2, 'STO 6', 'Store the result at address 6'], [3, 'END', 'Finish this program'], [4, 18, 'First number'], [5, 24, 'Second number'], [6, 0, 'Space for the result']]);
const symbolTable = table(['Label', 'Address', 'What is stored there initially?'], [['START', 0, 'LDD FIRST'], ['FIRST', 4, 18], ['SECOND', 5, 24], ['TOTAL', 6, 0]]);

